form .btn { transition: background-color 120ms ease-out; }
form .btn:active { background: #1a3fb0; }
@media (prefers-reduced-motion: no-preference) {
  form .btn { transition: background-color 120ms ease-out, transform 120ms cubic-bezier(.23,1,.32,1); }
  form .btn:active { transform: scale(.97); }
}

